from collections import defaultdict

# Convert a number to a given base
def to_base(n, k):
    if n == 0:
        return [0]
    digits = []
    while n:
        digits.append(int(n % k))
        n //= k
    return digits[::-1]

# Calculate the sum of digits in a given base
def sum_of_digits_in_base(n, k):
    return sum(map(int, to_base(n, k)))

# Calculate the number of distinct subsequences
def num_distinct_subsequences(n, k):
    mod = 10 ** 9 + 7
    dp = [0] * (n + 1)
    dp[0] = 1  # The empty subsequence is considered a subsequence

    for i in range(1, n + 1):
        for j in range(1, k + 1):
            if sum_of_digits_in_base(i * 10 + j - 1, k) > j:
                dp[j] = (dp[j] + dp[j - 1] * 9 % mod) % mod

    return dp[k]

