from math import pow
from typing import Tuple

MOD = 10**9 + 7

def prefix_sum(ids: list, n: int, w: list) -> int:
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = (prefix[i] * 10 + w[i] - pow(10, ids[i], MOD)) % MOD
    return prefix[-1] if n else 0

def rolling_sum(ids: list, n: int, values: list, v: int, mq: int, q1: int) -> int:
    if mq > 0:
        for i in range(n):
            v = (values[i] - v * mq if ids[i] else v * mq) % MOD
    prefix = [0] * (q1 + mq + 1)
    for i in range(q1):
        prefix[i] = values[i] + (prefix[i] if i > 0 else 0) 
        if mq > 0:
            prefix[i] = (prefix[i] * 10 + v - values[i] * mq) % MOD
    prefix[-1] = values[q1 - 1]
    for i in range(q1, q1 + mq):
        if q1 < i < q1 + mq:
            prefix[i] = (prefix[i] * 10 - prefix[i - 1] * 9) % MOD
        prefix[i] = (prefix[i] + 9 if i > 0 else 9) if i else 9
        if mq > 0:
            prefix[i] = (prefix[i] * 10 - prefix[i - 1] * mq) % MOD
    return(prefix[q1] + (prefix[q1] - prefix[-1] * 9 + 9) * (mq // q1) % MOD)

def formula(a: list, n: int) -> int:
    return (2 * rolling_sum([0], n, [10], 10, n, n) - rolling_sum([-1], n, [-2], -2, -1, n)) % MOD if a[0] else 0

def solve(n, q, a, w, queries):
    if n == 1:
        return 0
    even, odd, ans, old = 1, 1, 0, 0
    for i in range(n):
        even *= 10 - pow(10, a[i], MOD) if w[i] % 2 else 10
        odd *= 10 - pow(10, a[i], MOD) if w[i] % 2 else 10
        old += pow(10, w[i], MOD)
        odd = (odd * n - formula([a[i]], 1) + old) % MOD
        ans = (ans + even * w[i]) % MOD
    for x, y in queries:
        if x < 0:
            even %= MOD
            odd *= 10
        else:
            odd -= pow(10, a[x], MOD) - old
        new = formula([a[x]], 1)
        odd = (odd + new - old) % MOD
        ans += even + (odd * x) % MOD
        ans %= MOD
    return ans

