        if k not in self.segments:
            self.segments[k] = []
        self.segments[k].append((l, r))

    def calculate_danger(self, l, r):
        total_danger = 0
        for k, segments in sorted(self.segments.items()):
            for segments_start, segments_end in segments:
                if l <= segments_start < r and (l <= segments_end < r) and (segments_start < l <= segments_end):
