                    dangerous_start = max(segments_start, l)
                    danger_count = segments_end - dangerous_start + 1
                    danger_value = (abs(k) * danger_count, abs(k) * danger_count)
                    total_danger += danger_value[0] + danger_value[1]
        return total_danger

