        else:  # Update the segment
            if k == 0 or segments[b - 1] < k:
                segments[a * n + b] = k
            else:
                segments[a * n + b] = segments[b - 1]
                if tree.merge(tree.query(a * n + b) + k) < tree.query(a * n + b):
                    tree.update(a * n + b, k)

    return all(tree.query(a * n + b) == n for a, b in segments.items())

def build_tree(n):
    tree = [0] * (2 * n)
    while len(tree) < 2 * n:
        tree.append(0)
    return tree

def merge(x, y):
