        if x1 == x2:
            self.danger_value[x1] += y
        else:
            self.compute_danger_value(x1, x2, y)

    def compute_danger_value(self, x1, x2, y):
        if y > 0:
            self.compute_left(x1, x2, -y)
        for i in range(x1 + 1, x2):
            index = bisect.bisect(self.snakes, i - 1)
            if index > 0:
                danger = (-self.danger_value[i - 1] if i - 1 < 0 else self.danger_value[i - 1]) - self.snakes[index-1]
                if danger > 0:
                    y1 = self.danger_value[i]
                    self.snakes.insert(index, y1)
                    self.danger_value[i] = y1 + y
                    break
            elif index > 1:
                danger = -self.danger_value[0] - self.snakes[index-2]
                if y < danger:
                    y2 = self.danger_value[0] if 0 < x1 - 1 else -danger
                    self.snakes[:index-1] = self.snakes[index-2:]
                    self.danger_value[:index-1] = self.snakes[-1:] + self.danger_value[index-1:]
                    self.snakes.insert(index-1, y2)
                    self.danger_value[i] = y2 + y
                    break
            else:
                self.snakes.insert(index, y)
                self.danger_value[i] = y
                break

