from math import pow, mod

BASE = 1000000007
MODULO = pow(BASE, 0, BASE - 1)

def extended_gcd(a, b):
    """
    Returns (g, x, y) such that a*x + b*y = g = gcd(a, b)
    """
    if a == 0:
        return (b, 0, 1)
    else:
        g, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return (g, x, y)

def mod_inverse(a, m=BASE):
    """
    Returns the modular inverse of a modulo m.
    """
    _, x, _ = extended_gcd(a, m)
    if x >= 0:
        return x
    else:
        return (x + m) % m

modular_pow = lambda x, n, m: (pow(x, n), n)

