                else:
                    uncaller[i] = base_log[update[i] - 1][1]
                    sub_mask_bits.append(update[i])

        # subset merge
        last_work = None
        for traj, i, diff in zip(sub_mask_bits[::2], sub_mask_bits[1::2], sub_mask_bits):
            if traj is None:
                continue
            next_diff = diff
            for id in sorted(traj):
                if last_work is None or uncaller[id] == uncaller[id-1]:
                    uncaller[id] = uncaller[id-1]
                    next_diff -= 1 if next_diff else 0
                    if next_diff == 0:
