            if next_diff:
                uncaller[last_work[0]] = uncaller[last_work[1]]
                uncaller[last_work[1]] = work[len(work)-1]
                work.append(next_diff)

        work.append(work.count(work[0]) - 1)

        # all in sequence
        uncaller = [0] * n

        # unify assets
        work.sort()

        uncaller[-1] = uncaller[-2] + 1
