from collections import deque

class HogwartsEntrance:
    def __init__(self):
        self.risks = []
        self.segments = {}

    def add_snake(self, l, r, k):
        if k == 0:
            return
        for x in range(l, r-1):
            self.risks.append((-x*k, x*k))
        if r not in self.segments:
            if l not in self.segments:
                self.seg = deque([r])
            else:
                self.seg = deque([r, l])
        else:
            self.seg.append(r)

    def danger_value(self, l, r):
        solutions = []
        while l < r:
            if self.risks[0][0] < 0:
                solutions.append(self.risks.popleft())
                l += 1
            elif self.risks[-1][0] < 0:
                solutions.append(self.risks.pop())
                l += 1
            elif self.seg[0] <= l < self.seg[-1]:
                break
            else:
                l += 1
        for s in sorted(solutions + [(0, min(self.risks[0][1], self.risks[-1][1]))]):
            l, r = s
            for other in [self.risks[l:], self.risks[-r:]:
                if -other[1] <= -1*l[-1] <= -1*r[0] <= other[1]:
                    break
            else:
                break
        if not solutions:
            return 0
        return sum(i[1] for i in solutions) + other[1][1]

