        for i in range(si-1, i)
            y1 = self.ys.get(i - 1, y1)
            idx = bisect_right(self.ys, i)
            if idx > i and (abs(self.ys[idx - 1]) <= abs(ki) or y1 < 0):
                x = i
                break
        for i in range(ri):
