from collections import deque

def make_palindrome():
    T = int(input())
    for _ in range(T):
        N, M = map(int, input().split())
        S = [input().strip() for _ in range(N)]

        graph = [[] for _ in range(26)]
        visited = [0] * 26

        for i in range(N):
            for j in range(M-1, -1, -1):
                current = S[i][j]
                nxt = S[i][M-1-j]
                graph[ord(current) - ord('a')].append(ord(nxt) - ord('a'))
                graph[ord(nxt) - ord('a')].append(ord(current) - ord('a'))

        def bfs(node):
            queue = deque([(node, 0)])
            visited[node] = 1

            while queue:
                current, steps = queue.popleft()

                if steps == M//2:
                    return True

                for nxt in graph[current]:
                    if visited[nxt] == 0:
                        visited[nxt] = 1
                        queue.append((nxt, steps + 1))

            return False

        move_count = 0
        for node in range(26):
            if bfs(node):
                move_count += 1

        print(move_count) if make_palindrome() == 0 else print(-1)

